/**
 * Offline receive and canonical-wire audit.
 *
 * <p>Each datagram is read as consecutive cleartext envelopes. Packet numbers are reconstructed per
 * level; routing, key, range, authentication, duplication and key-epoch precedence is then applied.
 * Surviving packets decode their frames with the retained TLS-Attacker frame table, and every packet
 * is one transaction that either commits all of its effects or rolls all of them back. Accepted
 * packets are re-encoded as canonical envelopes, hashed, and summarized with the committed snapshot.
 */
public final class ReceiveAudit {

    static final long MAX62 = (1L << 62) - 1;
    static final long MAX60 = 1L << 60;
    static final String[] LVL = {"I", "H", "A"};
    static final byte[] VERSION = {0, 0, 0, 1};
    static final String ENCODING = "FRAME_ENCODING_ERROR";
