    static final String STREAM_STATE = "STREAM_STATE_ERROR";
    static final String STREAM_LIMIT = "STREAM_LIMIT_ERROR";
    static final String CID_LIMIT = "CONNECTION_ID_LIMIT_ERROR";
    static final String KEY_UPDATE = "KEY_UPDATE_ERROR";
    static final String PEER_CLOSE = "PEER_CLOSE";

    /* ==================================== holders ==================================== */

    static final class Stream {
        long high;
        long sendMax;
        Long finalSize;
        Long reset;
        Long stop;
        boolean listed;
        final Store bytes = new Store();
    }

    static final class PeerCid {
        final byte[] cid;
        final byte[] token;
        PeerCid(byte[] cid, byte[] token) {
            this.cid = cid;
            this.token = token;
        }
    }

    /** One framed envelope. */
    static final class Pkt {
        int event;
        int index;
        int offset;
        int end;
        boolean bad;
        int lvl;
        int width = 1;
        int phase;
        long raw;
        long expected;
        long pn = -1;
        int destination = -1;
        byte[] dcid = new byte[0];
        byte[] scid = new byte[0];
        byte[] token = new byte[0];
        byte[] payload = new byte[0];
    }

    /** Packet transaction failure: closes the connection and rolls the packet back. */
    static final class Fail extends RuntimeException {
        final String code;
        final long offset;
        Fail(String code, long offset) {
            super(code);
            this.code = code;
            this.offset = offset;
        }
        @Override
        public synchronized Throwable fillInStackTrace() {
            return this;
        }
    }

    /** Truncated or non-minimal body marker, mapped onto FRAME_ENCODING_ERROR by the frame loop. */
    static final class Trunc extends RuntimeException {
        @Override
        public synchronized Throwable fillInStackTrace() {
            return this;
        }
    }

    /* ==================================== byte ledger ==================================== */

    /** Sparse byte ledger of disjoint, non-adjacent runs. */
    static final class Store {
        final TreeMap<Long, byte[]> map = new TreeMap<>();
        long unique;

        /** Merges equal overlaps; returns false when an overlapping byte differs. */
        boolean put(long off, byte[] data, List<Runnable> journal) {
            if (data.length == 0) return true;
            ArrayList<Long> oldKeys = new ArrayList<>();
            ArrayList<byte[]> oldVals = new ArrayList<>();
            long s = off;
            long e = off + data.length;
            boolean progress = true;
            while (progress) {
                progress = false;
                Map.Entry<Long, byte[]> floor = map.floorEntry(s);
                if (floor != null && floor.getKey() + floor.getValue().length >= s && !has(oldKeys, floor.getKey())) {
                    keys(oldKeys, oldVals, floor.getKey(), floor.getValue());
                    if (floor.getKey() + floor.getValue().length > e) e = floor.getKey() + floor.getValue().length;
                    s = floor.getKey();
                    progress = true;
                }
                Iterator<Map.Entry<Long, byte[]>> it = map.tailMap(s, true).entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<Long, byte[]> entry = it.next();
                    long start = entry.getKey();
                    if (start > e) break;
                    if (has(oldKeys, start)) continue;
                    keys(oldKeys, oldVals, start, entry.getValue());
                    if (start + entry.getValue().length > e) e = start + entry.getValue().length;
                    progress = true;
                }
            }
            for (int i = 0; i < oldKeys.size(); i++) {
                long xs = oldKeys.get(i);
                byte[] xd = oldVals.get(i);
                long os = Math.max(xs, off);
                long oe = Math.min(xs + xd.length, off + data.length);
                for (long k = os; k < oe; k++) {
                    if (xd[(int) (k - xs)] != data[(int) (k - off)]) return false;
                }
            }
            byte[] merged = new byte[(int) (e - s)];
            long oldSum = 0;
            for (int i = 0; i < oldKeys.size(); i++) {
                byte[] value = oldVals.get(i);
                oldSum += value.length;
                System.arraycopy(value, 0, merged, (int) (oldKeys.get(i) - s), value.length);
            }
            System.arraycopy(data, 0, merged, (int) (off - s), data.length);
            ArrayList<Map.Entry<Long, byte[]>> before = new ArrayList<>(map.entrySet());
            for (Long key : oldKeys) map.remove(key);
            map.put(s, merged);
            long delta = (e - s) - oldSum;
            unique += delta;
            final long ns = s;
            journal.add(
                    () -> {
                        map.clear();
                        for (Map.Entry<Long, byte[]> entry : before) map.put(entry.getKey(), entry.getValue());
                        unique -= delta;
                    });
            return true;
        }

        private static void keys(List<Long> keyList, List<byte[]> valList, long key, byte[] value) {
            keyList.add(key);
            valList.add(value);
        }

        private static boolean has(List<Long> keys, long key) {
            for (int i = 0; i < keys.size(); i++) if (keys.get(i) == key) return true;
            return false;
        }

        long prefix() {
            byte[] first = map.get(0L);
            return first == null ? 0 : first.length;
        }

        byte[] prefixBytes() {
            byte[] first = map.get(0L);
            return first == null ? new byte[0] : first;
        }

        List<Object> ranges() {
            List<Object> out = new ArrayList<>();
            for (Map.Entry<Long, byte[]> entry : map.entrySet()) {
                long start = entry.getKey();
                out.add(Arrays.asList(start, start + entry.getValue().length));
            }
            return out;
        }
    }

    /* ==================================== interval ledger ==================================== */

    /** Merged half-open integer intervals (acknowledged ranges, retired sequences). */
    static final class Ledger {
        final TreeMap<Long, Long> map = new TreeMap<>(); // start -> exclusive end
        long count;

        boolean covers(long value) {
            Map.Entry<Long, Long> floor = map.floorEntry(value);
            return floor != null && floor.getValue() > value;
        }

        void add(long a, long b, List<Runnable> journal) {
            if (b <= a) return;
            long s = a;
            long e = b;
            ArrayList<Long> oldKeys = new ArrayList<>();
            ArrayList<Long> oldEnds = new ArrayList<>();
            boolean progress = true;
            while (progress) {
                progress = false;
                Map.Entry<Long, Long> floor = map.floorEntry(s);
                if (floor != null && floor.getValue() >= s && !has(oldKeys, floor.getKey())) {
                    oldKeys.add(floor.getKey());
                    oldEnds.add(floor.getValue());
                    if (floor.getValue() > e) e = floor.getValue();
                    s = floor.getKey();
                    progress = true;
                }
                Iterator<Map.Entry<Long, Long>> it = map.tailMap(s, true).entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<Long, Long> entry = it.next();
                    long start = entry.getKey();
                    if (start > e) break;
                    if (has(oldKeys, start)) continue;
                    oldKeys.add(start);
                    oldEnds.add(entry.getValue());
                    if (entry.getValue() > e) e = entry.getValue();
                    progress = true;
                }
            }
            long oldSum = 0;
            for (int i = 0; i < oldKeys.size(); i++) oldSum += oldEnds.get(i) - oldKeys.get(i);
            ArrayList<Map.Entry<Long, Long>> before = new ArrayList<>(map.entrySet());
            for (Long key : oldKeys) map.remove(key);
            map.put(s, e);
            long delta = (e - s) - oldSum;
            count += delta;
            final long ns = s;
            journal.add(
                    () -> {
                        map.clear();
                        for (Map.Entry<Long, Long> entry : before) map.put(entry.getKey(), entry.getValue());
                        count -= delta;
                    });
        }

        private static boolean has(List<Long> keys, long key) {
            for (int i = 0; i < keys.size(); i++) if (keys.get(i) == key) return true;
            return false;
        }

        List<Object> intervals() {
            List<Object> out = new ArrayList<>();
            for (Map.Entry<Long, Long> entry : map.entrySet()) {
                out.add(Arrays.asList(entry.getKey(), entry.getValue()));
            }
            return out;
        }

        long prefix() {
            Long end = map.get(0L);
            return end == null ? 0 : end;
        }

        byte[] hashBytes() {
            ByteArrayOutputStream out = new ByteArrayOutputStream(16 * map.size());
            for (Map.Entry<Long, Long> entry : map.entrySet()) {
                writeBE(out, entry.getKey());
                writeBE(out, entry.getValue());
            }
            return out.toByteArray();
        }
    }

    static void writeBE(ByteArrayOutputStream out, long value) {
        for (int i = 56; i >= 0; i -= 8) out.write((int) (value >>> i) & 0xff);
    }

    /* ==================================== cursor ==================================== */

    static final class Cur {
        final byte[] b;
        int pos;
        Cur(byte[] b) {
            this.b = b;
        }
        Cur(byte[] b, int pos) {
            this.b = b;
            this.pos = pos;
        }

        int left() {
            return b.length - pos;
        }

        private long read(int[] widthOut) {
            if (pos >= b.length) throw new Trunc();
            int first = b[pos] & 0xff;
            int width = 1 << (first >> 6);
            if (left() < width) throw new Trunc();
            long value = first & 0x3f;
            for (int i = 1; i < width; i++) value = (value << 8) | (b[pos + i] & 0xff);
            pos += width;
            if (widthOut != null) widthOut[0] = width;
            return value;
        }

        /** Body/header varint; overlong encodings are allowed. */
        long varint() {
            return read(null);
        }

        /** Frame type varint; must use its shortest encoding. */
        long type() {
            int[] width = new int[1];
            long value = read(width);
            if (width[0] != minWidth(value)) throw new Trunc();
            return value;
        }

        int u8() {
            if (pos >= b.length) throw new Trunc();
            return b[pos++] & 0xff;
        }

        byte[] take(long n) {
            if (n < 0 || n > left()) throw new Trunc();
            byte[] out = Arrays.copyOfRange(b, pos, pos + (int) n);
            pos += (int) n;
            return out;
        }

        byte[] rest() {
            byte[] out = Arrays.copyOfRange(b, pos, b.length);
            pos = b.length;
            return out;
        }
    }

    static int minWidth(long value) {
        if (value < 64) return 1;
        if (value < 16384) return 2;
        if (value < (1L << 30)) return 4;
        return 8;
    }

    static byte[] vi(long value) {
        return VariableLengthIntegerEncoding.encodeVariableLengthInteger(value);
    }

    /** Closest nonnegative congruent number to expected; ties choose the larger value. */
    static long reconstruct(long raw, int width, long expected) {
        long modulus = 1L << (8 * width);
        long half = modulus >>> 1;
        long delta = Math.floorMod(raw - expected, modulus);
        long near = expected + delta;
        if (delta > half && near - modulus >= 0) return near - modulus;
        return near;
    }

    /* ==================================== trace configuration ==================================== */

    private long connLimit;
    private long streamLimit;
    private long clientBidiLimit;
    private long clientUniLimit;
    private int cidLimit;
    private long localBidi;
    private long localUni;
    private byte[][] localCids;

    /* ==================================== committed state ==================================== */

    private final boolean[] keys = {true, false, false};
    private final long[] largest = {-1, -1, -1};
    @SuppressWarnings("unchecked")
    private final HashSet<Long>[] seen = (HashSet<Long>[]) new HashSet<?>[3];

    private final TreeMap<Long, long[]> epochStats = new TreeMap<>(); // epoch -> min,max,count
    private long currentEpoch;

    private final HashMap<Long, Stream> streams = new HashMap<>();
    private final Store[] crypto = {new Store(), new Store(), new Store()};
    private final Ledger[] acks = {new Ledger(), new Ledger(), new Ledger()};
    private final long[][] ecn = new long[3][3];

    private final TreeMap<Long, PeerCid> peerObserved = new TreeMap<>();
    private final HashMap<String, Long> cidOwner = new HashMap<>();
    private final TreeSet<Long> peerActive = new TreeSet<>();
    private long retireThreshold;
    private final Ledger retiredLocal = new Ledger();

    private long openedBidi;
    private long openedUni;
    private long used;
    private long sendMaxData;
    private long sendMaxStreamsBidi;
    private long sendMaxStreamsUni;

    private boolean closed;
    private Map<String, Object> closedRow;

    private final ArrayList<Runnable> journal = new ArrayList<>();
    private final List<Object> packetRows = new ArrayList<>();
    private final List<Object> datagramRows = new ArrayList<>();
    private MessageDigest digest;

    /* ==================================== entry point ==================================== */

    public Map<String, Object> audit(Main.Trace trace) {
        for (int i = 0; i < 3; i++) seen[i] = new HashSet<>();
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException(impossible);
        }
        connLimit = trace.connection;
        streamLimit = trace.stream;
        clientBidiLimit = trace.bidi;
        clientUniLimit = trace.uni;
        cidLimit = trace.cidLimit;
        localBidi = trace.localBidi;
        localUni = trace.localUni;
        localCids = trace.localCids.toArray(new byte[0][]);

        for (int level = 0; level < 3; level++) {
            long seed = trace.received[level];
            if (seed >= 0) {
                largest[level] = seed;
                seen[level].add(seed);
                if (level == 2) epochStats.put(0L, new long[] {seed, seed, 1});
            }
        }
        peerObserved.put(0L, new PeerCid(trace.peerCid, trace.peerToken));
        cidOwner.put(Main.hex(trace.peerCid), 0L);
        peerActive.add(0L);

        for (int event = 0; event < trace.events.size(); event++) {
            Main.Event entry = trace.events.get(event);
            if (entry.keys != null) {
                if (!closed) applyKeys(entry.keys);
                continue;
            }
            datagram(event, entry.wire, entry.auth);
        }
        return result();
    }

    private void applyKeys(List<String> list) {
        Arrays.fill(keys, false);
        for (String name : list) {
            if (name.equals("I")) keys[0] = true;
            else if (name.equals("H")) keys[1] = true;
            else keys[2] = true;
        }
    }

    /* ==================================== datagram framing ==================================== */

    private void datagram(int event, byte[] wire, List<Long> auth) {
        ByteArrayOutputStream acceptedBytes = new ByteArrayOutputStream();
        int accepted = 0;
        int attempts = 0;
        int pos = 0;
        while (pos < wire.length) {
            Pkt pkt = header(wire, pos);
            pkt.event = event;
            pkt.index = attempts++;
            Long annotation = pkt.index < auth.size() ? auth.get(pkt.index) : null;
            if (process(pkt, annotation, acceptedBytes)) accepted++;
            if (pkt.bad) break;
            pos = pkt.end;
        }
        byte[] concat = acceptedBytes.toByteArray();
        datagramRows.add(
                Main.object(
                        "event",
                        (long) event,
                        "packets",
                        (long) attempts,
                        "accepted",
                        (long) accepted,
                        "bytes",
                        (long) concat.length,
                        "sha256",
                        sha(concat)));
    }

    private Pkt header(byte[] wire, int pos) {
        Pkt pkt = new Pkt();
        pkt.offset = pos;
        int first = wire[pos] & 0xff;
        pkt.bad = true;
        if ((first & 0x80) != 0) {
            int base = first & 0xfc;
            if (base != 0xc0 && base != 0xe0) return pkt;
            pkt.lvl = base == 0xc0 ? 0 : 1;
            pkt.width = (first & 3) + 1;
            Cur cur = new Cur(wire, pos + 1);
            try {
                if (!Arrays.equals(cur.take(4), VERSION)) return pkt;
                int dcidLength = cur.u8();
                if (dcidLength > 20) return pkt;
                pkt.dcid = cur.take(dcidLength);
                int scidLength = cur.u8();
                if (scidLength > 20) return pkt;
                pkt.scid = cur.take(scidLength);
                if (pkt.lvl == 0) {
                    long tokenLength = cur.varint();
                    if (tokenLength > cur.left()) return pkt;
                    pkt.token = cur.take(tokenLength);
                }
                long length = cur.varint();
                if (length < pkt.width) return pkt;
                long end = (long) cur.pos + length;
                if (end > wire.length) return pkt;
                pkt.raw = pnBytes(wire, cur.pos, pkt.width);
                cur.pos += pkt.width;
                pkt.payload = cur.take(end - cur.pos);
                pkt.end = (int) end;
                pkt.bad = false;
            } catch (Trunc truncated) {
                pkt.bad = true;
            }
            return pkt;
        }
        if ((first & 0xc0) != 0x40 || (first & 0x18) != 0) return pkt;
        pkt.lvl = 2;
        pkt.phase = (first >> 2) & 1;
        pkt.width = (first & 3) + 1;
        int cidWidth = localCids[0].length;
        if ((long) pos + 1 + cidWidth + pkt.width > wire.length) return pkt;
        Cur cur = new Cur(wire, pos + 1);
        pkt.dcid = cur.take(cidWidth);
        pkt.raw = pnBytes(wire, cur.pos, pkt.width);
        cur.pos += pkt.width;
        pkt.payload = cur.rest();
        pkt.end = wire.length;
        pkt.bad = false;
        return pkt;
    }

    private static long pnBytes(byte[] data, int pos, int width) {
        long value = 0;
        for (int i = 0; i < width; i++) value = (value << 8) | (data[pos + i] & 0xffL);
        return value;
    }

    /* ==================================== packet pipeline ==================================== */

    /** Returns true when the packet was accepted and contributes a canonical envelope. */
    private boolean process(Pkt pkt, Long annotation, ByteArrayOutputStream datagramBytes) {
        if (pkt.bad) {
            add(pkt, null, null, null, "BAD_HEADER", null);
            return false;
        }
        int level = pkt.lvl;
        pkt.expected = largest[level] < 0 ? 0 : largest[level] + 1;
        pkt.pn = reconstruct(pkt.raw, pkt.width, pkt.expected);

        String discard = null;
        if (closed) discard = "CLOSED";
        if (discard == null) {
            pkt.destination = route(pkt.dcid);
            if (pkt.destination < 0) discard = "DROP_CID";
        }
        if (discard == null && !keys[level]) discard = "NO_KEY";
        if (discard == null && pkt.pn > MAX62) discard = "PN_RANGE";
        Long generation = null;
        if (discard == null) {
            if (level == 2) {
                if (annotation != null && annotation <= MAX62 && generationAllowed(annotation, pkt.phase)) {
                    generation = annotation;
                } else {
                    discard = "AUTH";
                }
            } else if (annotation == null || annotation != 0L) {
                discard = "AUTH";
            }
        }
        if (discard != null) {
            add(pkt, LVL[level], pkt.pn, null, discard, null);
            return false;
        }
        Long epoch = level == 2 ? generation : null;
        if (seen[level].contains(pkt.pn)) {
            add(pkt, LVL[level], pkt.pn, epoch, "DUPLICATE", null);
            return false;
        }
        if (level == 2 && !orderOk(generation, pkt.pn)) {
            add(pkt, LVL[level], pkt.pn, epoch, KEY_UPDATE, null);
            close(pkt, 0, KEY_UPDATE);
            return false;
        }
        int mark = journal.size();
        String status;
        try {
            byte[] payload = frames(pkt, level);
            if (level == 2) acceptEpoch(generation, pkt.pn);
            seen[level].add(pkt.pn);
            if (pkt.pn > largest[level]) largest[level] = pkt.pn;
            byte[] envelope = envelope(pkt, payload);
            journal.clear();
            status = closeStatus;
            if (status != null) close(pkt, closeOffset, status);
            datagramBytes.writeBytes(envelope);
            add(pkt, LVL[level], pkt.pn, epoch, status == null ? "OK" : status, sha(envelope));
            return true;
        } catch (Fail failure) {
            undoTo(mark);
            add(pkt, LVL[level], pkt.pn, epoch, failure.code, null);
            close(pkt, failure.offset, failure.code);
            status = failure.code;
            return false;
        } finally {
            closeStatus = null;
            closeOffset = 0;
            if (status != null && !status.equals("OK") && !status.equals(PEER_CLOSE)) {
                /* every frame/semantic failure closed the connection above */
            }
        }
    }

    private int route(byte[] dcid) {
        for (int i = 0; i < localCids.length; i++) {
            if (Arrays.equals(localCids[i], dcid) && !retiredLocal.covers(i)) return i;
        }
        return -1;
    }

    private boolean generationAllowed(long generation, int phase) {
        if ((generation & 1) != phase) return false;
        if (generation == currentEpoch) return true;
        if (generation == currentEpoch - 1 && currentEpoch >= 1) return true;
        return generation == currentEpoch + 1 && currentEpoch < MAX62;
    }

    /** All packet numbers of a higher accepted epoch must exceed all of a lower accepted epoch. */
    private boolean orderOk(long generation, long pn) {
        for (Map.Entry<Long, long[]> entry : epochStats.entrySet()) {
            long other = entry.getKey();
            if (other == generation) continue;
            long[] stats = entry.getValue();
            if (generation > other) {
                if (pn <= stats[1]) return false;
            } else if (pn >= stats[0]) {
                return false;
            }
        }
        return true;
    }

    private void acceptEpoch(long generation, long pn) {
        if (generation == currentEpoch + 1) {
            final long previous = currentEpoch;
            currentEpoch = generation;
            journal.add(() -> currentEpoch = previous);
        }
        long[] stats = epochStats.get(generation);
        if (stats == null) {
            epochStats.put(generation, new long[] {pn, pn, 1});
            journal.add(() -> epochStats.remove(generation));
            return;
        }
        final long oldMin = stats[0];
        final long oldMax = stats[1];
        final long oldCount = stats[2];
        if (pn < stats[0]) stats[0] = pn;
        if (pn > stats[1]) stats[1] = pn;
        stats[2] = oldCount + 1;
        journal.add(
                () -> {
                    stats[0] = oldMin;
                    stats[1] = oldMax;
                    stats[2] = oldCount;
                });
    }

    private void close(Pkt pkt, long offset, String code) {
        closed = true;
        closedRow =
                Main.object(
                        "event",
                        (long) pkt.event,
                        "packet",
                        (long) pkt.index,
                        "offset",
                        offset,
                        "code",
                        code);
    }

    private void undoTo(int mark) {
        for (int i = journal.size() - 1; i >= mark; i--) journal.get(i).run();
        while (journal.size() > mark) journal.remove(journal.size() - 1);
    }

    private void add(Pkt pkt, String level, Long pn, Long epoch, String status, String sha) {
        packetRows.add(
                Main.object(
                        "event",
                        (long) pkt.event,
                        "packet",
                        (long) pkt.index,
                        "offset",
                        (long) pkt.offset,
                        "level",
                        level,
                        "pn",
                        pn,
                        "epoch",
                        epoch,
                        "status",
                        status,
                        "sha256",
                        sha));
    }

    private String sha(byte[] bytes) {
        digest.reset();
        digest.update(bytes);
        return Main.hex(digest.digest());
    }

    /* ==================================== canonical envelope ==================================== */

    private byte[] envelope(Pkt pkt, byte[] payload) {
        int width = pkt.width;
        for (int candidate = 1; candidate <= 4; candidate++) {
            long mask = (1L << (8 * candidate)) - 1;
            if (reconstruct(pkt.pn & mask, candidate, pkt.expected) == pkt.pn) {
                width = candidate;
                break;
            }
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        if (pkt.lvl != 2) {
            out.write((pkt.lvl == 0 ? 0xc0 : 0xe0) | (width - 1));
            out.writeBytes(VERSION);
            out.write(pkt.dcid.length);
            out.writeBytes(pkt.dcid);
            out.write(pkt.scid.length);
            out.writeBytes(pkt.scid);
            if (pkt.lvl == 0) {
                out.writeBytes(vi(pkt.token.length));
                out.writeBytes(pkt.token);
            }
            out.writeBytes(vi((long) width + payload.length));
            writeLow(out, pkt.pn, width);
            out.writeBytes(payload);
        } else {
            out.write(0x40 | (pkt.phase << 2) | (width - 1));
            out.writeBytes(pkt.dcid);
            writeLow(out, pkt.pn, width);
            out.writeBytes(payload);
        }
        return out.toByteArray();
    }

    private static void writeLow(ByteArrayOutputStream out, long value, int width) {
        for (int i = width - 1; i >= 0; i--) out.write((int) ((value >>> (8 * i)) & 0xff));
    }

    /* ==================================== frame decoding ==================================== */

    private String closeStatus;
    private long closeOffset;

    private byte[] frames(Pkt pkt, int level) {
        byte[] payload = pkt.payload;
        if (payload.length == 0) throw new Fail(ENCODING, 0);
        Cur cur = new Cur(payload);
        ByteArrayOutputStream out = new ByteArrayOutputStream(payload.length);
        while (cur.pos < payload.length) {
            long start = cur.pos;
            long type;
            try {
                type = cur.type();
            } catch (Trunc trunc) {
                throw new Fail(ENCODING, start);
            }
            if (!supported(type)) throw new Fail(ENCODING, start);
            checkSender(type, level, start);
            ByteArrayOutputStream frame = new ByteArrayOutputStream();
            frame.writeBytes(vi(type));
            try {
                decode(type, cur, frame, pkt, level, start);
            } catch (Trunc trunc) {
                throw new Fail(ENCODING, start);
            }
            out.writeBytes(frame.toByteArray());
            if (type == 0x1c || type == 0x1d) {
                closeStatus = PEER_CLOSE;
                closeOffset = start;
                return out.toByteArray();
            }
        }
        return out.toByteArray();
    }

    private static boolean supported(long type) {
        return (type >= 0x00 && type <= 0x1e) || type == 0x30 || type == 0x31;
    }

    /** Types legal below the application level; every other frame is application-data space. */
    private static boolean allLevels(long type) {
        return type == 0x00 || type == 0x01 || type == 0x02 || type == 0x03 || type == 0x06 || type == 0x1c;
    }

    private void checkSender(long type, int level, long start) {
        if (type == 0x07 || type == 0x1e) throw new Fail(VIOLATION, start); // server-only
        if (!allLevels(type) && level != 2) throw new Fail(VIOLATION, start);
    }

    private void decode(long type, Cur cur, ByteArrayOutputStream out, Pkt pkt, int level, long start) {
        int code = (int) type;
        switch (code) {
            case 0x00: // PADDING: the single zero byte is the whole frame
            case 0x01: // PING
                return;
            case 0x02:
            case 0x03:
                ack(cur, out, level);
                return;
            case 0x04:
                resetStream(cur, out);
                return;
            case 0x05:
                stopSending(cur, out);
                return;
            case 0x06:
                crypto(cur, out, level);
                return;
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f:
                stream(code, cur, out);
                return;
            case 0x10: { // MAX_DATA
                long maximum = cur.varint();
                out.writeBytes(vi(maximum));
                commitMaxData(maximum);
                return;
            }
            case 0x11: { // MAX_STREAM_DATA
                long id = cur.varint();
                long maximum = cur.varint();
                out.writeBytes(vi(id));
                out.writeBytes(vi(maximum));
                Stream stream = reference(id, false);
                commitSendMax(stream, maximum);
                return;
            }
            case 0x12:
            case 0x13: { // MAX_STREAMS
                long maximum = cur.varint();
                if (maximum > MAX60) throw new Fail(ENCODING, start);
                out.writeBytes(vi(maximum));
                commitMaxStreams(maximum, code == 0x12);
                return;
            }
            case 0x14: { // DATA_BLOCKED
                long limit = cur.varint();
                out.writeBytes(vi(limit));
                return;
            }
            case 0x15: { // STREAM_DATA_BLOCKED
                long id = cur.varint();
                long limit = cur.varint();
                out.writeBytes(vi(id));
                out.writeBytes(vi(limit));
                reference(id, true);
                return;
            }
            case 0x16:
            case 0x17: { // STREAMS_BLOCKED
                long maximum = cur.varint();
                if (maximum > MAX60) throw new Fail(ENCODING, start);
                out.writeBytes(vi(maximum));
                return;
            }
            case 0x18:
                newConnectionId(cur, out);
                return;
            case 0x19:
                retireConnectionId(cur, out, pkt);
                return;
            case 0x1a:
            case 0x1b: // PATH_CHALLENGE / PATH_RESPONSE
                out.writeBytes(cur.take(8));
                return;
            case 0x1c:
                connectionClose(cur, out, true);
                return;
            case 0x1d:
                connectionClose(cur, out, false);
                return;
            case 0x30: // DATAGRAM without length: the packet remainder
                out.writeBytes(cur.rest());
                return;
            case 0x31: { // DATAGRAM with length
                long length = cur.varint();
                byte[] data = cur.take(length);
                out.writeBytes(vi(data.length));
                out.writeBytes(data);
                return;
            }
            default:
                throw new Fail(ENCODING, start);
        }
    }
